import re
p='Atm.Tests/Proprietes.cs'
s=open(p).read()

old_gen=s[s.index('    private static Gen<RetraitPlausible> Plausible =>'):s.index('    private static Gen<Operation> Operation =>')]
new_gen='''    /// <summary>Montant valide, puis déjà-retiré et solde choisis pour passer le plafond et les fonds.</summary>
    private static Gen<RetraitPlausible> PlausibleFor(Gen<int> amounts, Gen<Module> modules) =>
        from amount in amounts
        let fee = amount > 100 ? 5 : 0
        from withdrawn in Gen.Choose(0, (200 - amount) / 10).Select(i => i * 10)
        from balance in Gen.Choose((amount + fee) / 5, 50).Select(i => i * 5)
        from module in modules
        select new RetraitPlausible(new AccountState(balance, withdrawn), module, amount);

    /// <summary>Gros retraits sans (ou presque sans) billets de 50 : beaucoup de billets, donc plusieurs passages.</summary>
    private static Gen<Module> FewFifties =>
        from fifties in Gen.Choose(0, 5)
        from jammed in Gen.Elements<Denomination?>(Denomination.Fifty, Denomination.Fifty, null, Denomination.Ten)
        from twenties in Gen.Choose(2, 5)
        from tens in Gen.Choose(0, 5)
        select new Module(new NoteCounts(jammed == Denomination.Fifty ? fifties : fifties % 2, twenties, tens), jammed);

    private static Gen<RetraitPlausible> Plausible => Gen.Frequency(
        (3, PlausibleFor(Gen.Choose(1, 20).Select(i => i * 10), Module)),
        (1, PlausibleFor(Gen.Choose(9, 20).Select(i => i * 10), FewFifties)));

'''
s=s.replace(old_gen,new_gen)

s=s.replace('''(from retrait in Plausible from pass in Gen.Choose(1, 3) select new RetraitEnPanne(retrait, pass)).ToArbitrary();''',
'''(from retrait in Plausible from pass in Gen.Choose(1, 4) select new RetraitEnPanne(retrait, pass)).ToArbitrary();''')
s=s.replace('''/// <summary>Un retrait plausible avec un module qui tombe en panne au passage n° <see cref="FailingPass"/> (à partir de 1).</summary>''',
'''/// <summary>
/// Un retrait plausible avec un module qui tombe en panne. Le passage en panne est <see cref="Draw"/> ramené à 1..n+1, où n est
/// le nombre de passages du retrait sans panne : n+1 signifie que la panne arriverait après le dernier passage.
/// </summary>''')
s=s.replace('public sealed record RetraitEnPanne(RetraitPlausible Retrait, int FailingPass);','public sealed record RetraitEnPanne(RetraitPlausible Retrait, int Draw);')

# Refus : les deux générateurs
